// Safari refuses to use a redirected response for a navigation, so store a clean copy.
async function clean(res) {
  if (!res.redirected) return res;
  const body = await res.blob();
  return new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers });
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(PRECACHE.map(async (url) => {
      const res = await fetch(new Request(url, { cache: "reload" }));
      if (!res.ok) throw new Error("Precache failed for " + url + ": " + res.status);
      await cache.put(url, await clean(res));
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith(CACHE_PREFIX) && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

// Safari's <audio> asks for byte ranges ("Range: bytes=0-1") and will not play a clip
// unless it gets a proper 206 Partial Content answer, so serve ranges from the cache.
async function rangeResponse(res, range) {
  const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  const blob = await res.blob();
  const size = blob.size;
  if (!m) return new Response(blob, { status: 200, headers: res.headers });
  let start, end;
  if (m[1] === "") { start = Math.max(0, size - Number(m[2])); end = size - 1; }   // "bytes=-500"
  else { start = Number(m[1]); end = m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1); }
  if (start >= size || start > end) {
    return new Response(null, { status: 416, headers: { "Content-Range": "bytes */" + size } });
  }
  return new Response(blob.slice(start, end + 1), {
    status: 206,
    statusText: "Partial Content",
    headers: {
      "Content-Type": res.headers.get("Content-Type") || "audio/mpeg",
      "Content-Range": "bytes " + start + "-" + end + "/" + size,
      "Content-Length": String(end - start + 1),
      "Accept-Ranges": "bytes",
    },
  });
}

// Cache-first: everything is precached; anything new is fetched and kept.
self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // ignoreVary: GitHub Pages sends "Vary: Accept-Encoding", and media requests use a different
    // Accept-Encoding than the precache fetch, which would otherwise miss the cached clip.
    const hit = await cache.match(req, { ignoreSearch: true, ignoreVary: true });
    if (hit) {
      const range = req.headers.get("range");
      return range ? rangeResponse(hit, range) : hit;
    }
    if (req.mode === "navigate") {
      if (url.pathname.endsWith("/")) {
        const idx = await cache.match(url.pathname + "index.html", { ignoreVary: true });
        if (idx) return idx;
      } else if (await cache.match(url.pathname + "/", { ignoreVary: true })) {
        // "/colors" -> "/colors/" (like the web server does), so relative links keep working offline
        return Response.redirect(url.pathname + "/" + url.search, 301);
      }
    }
    try {
      const res = await fetch(req);
      if (res.status === 200 && res.type === "basic" && !req.headers.get("range")) {
        cache.put(req, await clean(res.clone())).catch(() => {});
      }
      return res;
    } catch (err) {
      if (req.mode === "navigate") {
        const home = await cache.match(new URL("./", self.location).pathname, { ignoreVary: true });
        if (home) return home;
      }
      throw err;
    }
  })());
});
